<?php
namespace App\\Http\\Controllers;use App\\Models\\User;use Illuminate\\Http\\Request;use Illuminate\\Support\\Facades\\Auth;use Illuminate\\Support\\Facades\\Hash;class AuthController extends Controller{public function loginForm(){return view('auth.login');}public function login(Request $r){$c=$r->validate(['email'=>'required|email','password'=>'required|string']);if(!Auth::attempt($c,$r->boolean('remember')))return back()->withErrors(['email'=>'Identifiants incorrects.'])->onlyInput('email');$r->session()->regenerate();return redirect()->intended(route('account'));}public function registerForm(){return view('auth.register');}public function register(Request $r){$d=$r->validate(['name'=>'required|string|max:120','email'=>'required|email|max:190|unique:users','phone'=>'nullable|string|max:30','password'=>'required|string|min:8|confirmed']);$d['password']=Hash::make($d['password']);$u=User::create($d);Auth::login($u);$r->session()->regenerate();return redirect()->route('account');}public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect()->route('home');}}
